<script setup lang="ts">
import{ref}from'vue';import{useEngine}from'../stores/engine';import{api}from'../services/api';import{confirmAction}from'../services/confirm';import{inputPayload,role,associationOwner,type Input}from'../types/engine';import Icon from'../components/Icon.vue';import Modal from'../components/Modal.vue';
const e=useEngine();const editing=ref(false),existing=ref(''),error=ref(''),success=ref('');const form=ref({name:'',speaker:'',enabled:true});
function edit(input?:Input){existing.value=input?.id||'';form.value={name:input?.name||'',speaker:input?.options?.speaker_id||'',enabled:input?.enabled??true};error.value='';editing.value=true}
async function save(){if(!await confirmAction('保存接收器更改','保存会重新加载接收器，当前投放可能短暂中断。'))return;try{await e.run(()=>api('/engine/v1/inputs'+(existing.value?'/'+encodeURIComponent(existing.value):''),existing.value?'PATCH':'POST',inputPayload(form.value,!!existing.value)));editing.value=false;success.value='接收器设置已保存'}catch(err){error.value=String(err)}}
async function remove(input:Input){if(!await confirmAction('删除接收器',`将删除「${input.name}」，当前投放可能中断。音箱记录会保留。`))return;try{await e.run(()=>api('/engine/v1/inputs/'+encodeURIComponent(input.id),'DELETE'));success.value='接收器已删除'}catch(err){error.value=String(err)}}
const owner=(id:string)=>associationOwner(e.inputs,id,existing.value,e.routes);
const speakerName=(input:Input)=>e.speakers.find(s=>s.id===input.options?.speaker_id)?.name||'未关联音箱';
</script>
<template><header class="page-header"><div><h1>AirPlay 接收器</h1><p class="page-description">在 iPhone 中看到的每个名字，都可以连接到指定音箱。</p></div><button :disabled="!e.snapshot?.engine_running||e.busy" @click="edit()"><Icon name="plus" :size="18"/>添加接收器</button></header><p v-if="error||e.snapshot?.inputs_error" class="notice error" role="alert"><Icon name="warning"/><span>{{error||e.snapshot?.inputs_error}}</span></p><p v-if="success" class="notice success" role="status"><Icon name="check"/><span>{{success}}</span></p><section class="panel receiver-list"><div class="panel-heading"><div><h2>你的接收器</h2><p>{{e.inputs.length}} 个入口 · 支持从 AirPlay 同时选择</p></div><span class="badge neutral">{{e.snapshot?.configuration_cached?'已保存的配置':'Engine Registry'}}</span></div><div v-if="!e.snapshot?.engine_running" class="section-note"><Icon name="info" :size="18"/><span>启动 Engine 后可编辑接收器。</span><RouterLink to="/settings">前往设置</RouterLink></div><div v-if="!e.inputs.length" class="empty-state"><span class="empty-icon"><Icon name="inputs" :size="35"/></span><h3>创建第一个 AirPlay 入口</h3><p>只需填写名称、关联音箱和启用状态。</p><button :disabled="!e.snapshot?.engine_running" @click="edit()"><Icon name="plus" :size="17"/>添加接收器</button></div><div v-for="input in e.inputs" :key="input.id" class="receiver-row"><span class="device-avatar" :class="{'avatar-disabled':!input.enabled}"><Icon name="inputs" :size="25"/></span><div class="receiver-copy"><h3>{{input.name}}</h3><p><Icon name="speaker" :size="14"/>{{speakerName(input)}}</p></div><span class="badge" :class="input.enabled&&e.snapshot?.state?.river?.producer===input.id?'blue':input.enabled?'teal':'neutral'">{{!input.enabled?'已停用':role(input.id,e.snapshot?.state?.river)}}</span><div class="row-actions"><button class="icon-button" :disabled="!e.snapshot?.engine_running" :aria-label="'编辑 '+input.name" @click="edit(input)"><Icon name="edit" :size="18"/></button><button class="icon-button danger" :disabled="!e.snapshot?.engine_running" :aria-label="'删除 '+input.name" @click="remove(input)"><Icon name="trash" :size="18"/></button></div></div><details class="help-details"><summary><Icon name="info" :size="15"/>接收器与音箱如何关联？</summary><p>当前每个接收器关联一台音箱，标识和端口自动管理。音箱与接收器为一对一关联，停用入口仍保留关联。主源由 River 决定，其他有效输入作为备用。</p></details></section><Modal :open="editing" :title="existing?'编辑接收器':'添加接收器'" @close="editing=false"><form @submit.prevent="save"><p class="dialog-description">接收器名称会显示在 AirPlay 设备列表中。</p><label>名称<input v-model="form.name" required maxlength="80" placeholder="例如：客厅 AirPlay" autofocus/></label><label>关联音箱<select v-model="form.speaker" required><option value="">选择音箱</option><option v-for="speaker in e.speakers" :key="speaker.id" :value="speaker.id" :disabled="!speaker.enabled||!!owner(speaker.id)">{{speaker.name}}{{owner(speaker.id)?'（已关联 '+owner(speaker.id)?.name+'）':''}}</option></select></label><p v-if="!e.speakers.length" class="field-help">请先在妙播音箱页搜索并添加设备。</p><label class="toggle-row"><span><b>启用接收器</b><small>允许设备发现和连接这个入口</small></span><input type="checkbox" role="switch" v-model="form.enabled"/></label><p v-if="error" class="notice error">{{error}}</p><div class="dialog-actions"><button type="button" class="secondary" @click="editing=false">取消</button><button :disabled="e.busy">保存</button></div></form></Modal></template>
